begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('bb251000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer,org integer default 1) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated','org_id',pg_temp.id(org))::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'regions-'||n||'@test.local' from generate_series(10,16) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'regions-a','Regions A'),(pg_temp.id(2),'regions-b','Regions B');
insert into public.memberships(organization_id,user_id,role) values
 (pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'viewer'),(pg_temp.id(1),pg_temp.id(12),'branch_user'),
 (pg_temp.id(2),pg_temp.id(13),'owner'),(pg_temp.id(1),pg_temp.id(14),'planner'),(pg_temp.id(1),pg_temp.id(15),'approver'),(pg_temp.id(1),pg_temp.id(16),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone)
 select pg_temp.id(100+n),pg_temp.id(1),'L'||lpad(n::text,2,'0'),'Location','branch','SA','Asia/Riyadh' from generate_series(1,21) n;
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone) values(pg_temp.id(150),pg_temp.id(2),'OTHER','Other','branch','SA','Asia/Riyadh');
insert into public.items(id,organization_id,code,name_en,product_group,unit_of_measure,unit_cost,currency)
 values(pg_temp.id(30),pg_temp.id(1),'P1','Part','Test','EA',1,'SAR');
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(101));
insert into public.stock_snapshots(organization_id,item_id,location_id,snapshot_date,quantity,allocated_quantity,unit_cost,currency,unit_of_measure)
 select pg_temp.id(1),pg_temp.id(30),pg_temp.id(100+n),'2026-01-08',0.1,0.2,1,'SAR','EA' from generate_series(1,21) n;
create temporary table fixture(input jsonb,report jsonb,saved uuid,assessment_input jsonb,assessment_report jsonb,assessment_id uuid);
insert into fixture(input) values('{"name_en":"Northern region","name_ar":"المنطقة الشمالية","location_codes":["L02","L01"],"confirmed":true}');
grant all on fixture to authenticated;
create function pg_temp.preview(overrides jsonb default '{}') returns jsonb language sql as $$select public.stock_region_preview(pg_temp.id(1),input||overrides) from fixture$$;
create function pg_temp.save(n integer default 50,overrides jsonb default '{}',fingerprint text default null) returns uuid language sql as $$select public.stock_region_save(pg_temp.id(1),input||overrides,pg_temp.id(n),coalesce(fingerprint,report->>'fingerprint')) from fixture$$;
create function pg_temp.stock_preview(overrides jsonb default '{}') returns jsonb language sql as $$select public.regional_stock_preview(pg_temp.id(1),assessment_input||overrides) from fixture$$;
create function pg_temp.stock_save(n integer default 70) returns uuid language sql as $$select public.regional_stock_save(pg_temp.id(1),assessment_input,pg_temp.id(n),assessment_report->>'fingerprint') from fixture$$;
select pg_temp.login(10); set local role authenticated;
update fixture set report=pg_temp.preview();
select is((select report#>>'{locations,0,code}' from fixture),'L01','canonical membership');
select is(pg_temp.preview('{"name_en":" Northern region ","location_codes":[" L01 ","L02"]}'),(select report from fixture),'trimmed order-independent preview');
select is(pg_temp.preview('{"name_ar":""}')#>'{input,name_ar}','null'::jsonb,'optional Arabic normalizes blank');
select throws_ok($$select pg_temp.preview('{"name_en":""}')$$,'MQ422',null,'name required');
select throws_ok($$select pg_temp.preview('{"name_ar":1}')$$,'MQ422',null,'Arabic must be text');
select throws_ok($$select pg_temp.preview('{"location_codes":["L01"]}')$$,'MQ422',null,'minimum two locations');
select throws_ok($$select pg_temp.preview('{"location_codes":["L01"," L01 "]}')$$,'MQ422',null,'duplicates rejected');
select throws_ok($$select pg_temp.preview('{"location_codes":["L01",null]}')$$,'MQ422',null,'null rejected');
select throws_ok($$select pg_temp.preview('{"location_codes":["L01","BAD/"]}')$$,'MQ422',null,'malformed code rejected');
select throws_ok($$select pg_temp.preview('{"location_codes":["L01","OTHER"]}')$$,'MQ404',null,'foreign membership opaque');
select throws_ok($$select pg_temp.preview('{"confirmed":false}')$$,'MQ422',null,'distinct holdings confirmation required');
select throws_ok($$select pg_temp.preview(jsonb_build_object('location_codes',(select jsonb_agg('L'||lpad(n::text,2,'0')) from generate_series(1,21) n)))$$,'MQ422',null,'maximum twenty locations');
select is(jsonb_array_length(pg_temp.preview(jsonb_build_object('location_codes',(select jsonb_agg('L'||lpad(n::text,2,'0')) from generate_series(1,20) n)))->'locations'),20,'twenty locations supported');
update fixture set saved=pg_temp.save();
select is(pg_temp.save(),(select saved from fixture),'stable region save retry');
select is(pg_temp.save(50,'{"location_codes":["L01","L02"]}'),(select saved from fixture),'retry order independent');
select throws_ok($$select pg_temp.save(50,'{"name_en":"Other"}')$$,'MQ409',null,'conflicting reuse rejected');
select throws_ok($$select pg_temp.save(51,'{}',repeat('a',64))$$,'MQ409',null,'changed preview rejected');
select throws_ok($$update public.stock_regions set required_location_ids=array[pg_temp.id(101),pg_temp.id(103)]$$,'42501',null,'no direct membership edits');
select throws_ok($$update public.stock_regions set archived_at=now()$$,'42501',null,'archive guarded');
select throws_ok($$delete from public.stock_regions$$,'42501',null,'no direct delete');
select throws_ok($$select app.stock_region_input('{}')$$,'42501',null,'input helper private');
update fixture set assessment_input=jsonb_build_object('assessment_name','Regional','item_code','P1','unit','EA','as_of','2026-01-15','region_id',saved,'confirmed',true);
update fixture set assessment_report=pg_temp.stock_preview();
select is((select assessment_report#>>'{totals,net}' from fixture),'-0.2','region keeps exact negative net');
select is((select assessment_report#>>'{region,id}' from fixture),(select saved::text from fixture),'assessment captures region identity');
select is((select assessment_report#>'{region,definition}' from fixture),(select report from fixture),'complete immutable region evidence copied');
select throws_ok($$select pg_temp.stock_preview('{"location_codes":["L01","L03"]}')$$,'MQ422',null,'caller cannot replace region membership');
select throws_ok($$select pg_temp.stock_preview('{"region_id":"invalid"}')$$,'MQ422',null,'invalid region id rejected');
select throws_ok($$select pg_temp.stock_preview('{"region_id":null}')$$,'MQ422',null,'null region id rejected');
select throws_ok($$select pg_temp.stock_preview(jsonb_build_object('region_id',pg_temp.id(999)))$$,'MQ404',null,'unknown region opaque');
update fixture set assessment_id=pg_temp.stock_save();
select is(pg_temp.stock_save(),(select assessment_id from fixture),'assessment retry stable');
reset role;
update public.locations set code='RENAMED',name_en='Renamed' where id=pg_temp.id(101);
set local role authenticated;
select is(pg_temp.stock_preview()#>>'{lines,1,location_id}',pg_temp.id(101)::text,'reuse follows fixed location identity after rename');
select is(pg_temp.stock_preview()#>>'{region,definition,locations,0,code}','L01','definition retains original label');
select throws_ok($$select pg_temp.stock_save(71)$$,'MQ409',null,'changed location evidence rejects stale assessment preview');
select is(pg_temp.stock_save(),(select assessment_id from fixture),'existing assessment retry keeps old labels');
select pg_temp.login(11);
select is((select count(*)::int from public.stock_regions),1,'viewer reads regions');
select throws_ok($$select pg_temp.save()$$,'MQ403',null,'viewer cannot create');
select throws_ok($$select public.stock_region_archive(pg_temp.id(1),(select saved from fixture))$$,'MQ403',null,'viewer cannot archive');
select pg_temp.login(15);
select throws_ok($$select pg_temp.save()$$,'MQ403',null,'approver cannot create');
select pg_temp.login(13,2);
select is((select count(*)::int from public.stock_regions),0,'cross tenant regions invisible');
select throws_ok($$select pg_temp.stock_preview()$$,'MQ404',null,'cross tenant reuse opaque');
select throws_ok($$select public.stock_region_archive(pg_temp.id(2),(select saved from fixture))$$,'MQ404',null,'foreign archive opaque');
select pg_temp.login(12);
select is((select count(*)::int from public.stock_regions),0,'partial member sees no region');
select is((select count(*)::int from public.regional_stock_assessments),0,'partial member sees no assessment');
select throws_ok($$select pg_temp.stock_preview()$$,'MQ404',null,'reuse needs every location');
reset role;
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(102));
set local role authenticated;
select is((select count(*)::int from public.stock_regions),1,'fully scoped member reads whole region');
select lives_ok($$select pg_temp.stock_preview()$$,'fully scoped member can inspect stock preview');
select throws_ok($$select public.stock_region_archive(pg_temp.id(1),(select saved from fixture))$$,'MQ403',null,'branch member still cannot archive');
select pg_temp.login(10);
reset role;
update public.locations set is_active=false where id=pg_temp.id(102);
set local role authenticated;
select throws_ok($$select pg_temp.stock_preview()$$,'MQ404',null,'inactive included location blocks reuse');
select is((select count(*)::int from public.stock_regions),1,'inactive location retains region history');
select is(pg_temp.stock_save(),(select assessment_id from fixture),'inactive location preserves assessment retry');
select is(public.stock_region_archive(pg_temp.id(1),(select saved from fixture)),(select saved from fixture),'archive works with inactive location');
select is(public.stock_region_archive(pg_temp.id(1),(select saved from fixture)),(select saved from fixture),'archive retry stable');
select is(pg_temp.save(),(select saved from fixture),'creation retry returns archived region');
reset role;
update public.locations set is_active=true where id=pg_temp.id(102);
set local role authenticated;
select throws_ok($$select pg_temp.stock_preview()$$,'MQ404',null,'archived region blocks new preview');
select throws_ok($$select pg_temp.stock_save(71)$$,'MQ404',null,'archived region blocks new save');
select is(pg_temp.stock_save(),(select assessment_id from fixture),'archiving does not block saved assessment retry');
select is((select report from public.regional_stock_assessments),(select assessment_report from fixture),'archiving never rewrites copied assessment');
select is((select report from public.stock_regions),(select report from fixture),'archiving leaves definition fixed');
select pg_temp.login(14);
select lives_ok($$select pg_temp.save(52,'{"location_codes":["RENAMED","L02"]}',pg_temp.preview('{"location_codes":["RENAMED","L02"]}')->>'fingerprint')$$,'planner can save overlapping replacement');
select pg_temp.login(16);
select lives_ok($$select public.stock_region_archive(pg_temp.id(1),(select id from public.stock_regions where request_id=pg_temp.id(52)))$$,'admin can archive another editor region');
reset role;
select is((select count(*)::int from public.audit_log where organization_id=pg_temp.id(1) and table_name='stock_regions' and operation='UPDATE'),2,'one audit per archive, no retry audit');
delete from public.stock_snapshots where organization_id=pg_temp.id(1);
delete from public.items where id=pg_temp.id(30);
set local role authenticated;
select is((select report from public.regional_stock_assessments),(select assessment_report from fixture),'source item deletion retains region assessment');
select pg_temp.login(10);
select is(pg_temp.stock_save(),(select assessment_id from fixture),'original author retry survives source deletion');
reset role;
delete from public.locations where id=pg_temp.id(103);
select is((select count(*)::int from public.stock_regions),2,'unrelated location deletion retains regions');
delete from public.locations where id=pg_temp.id(101);
select is((select count(*)::int from public.stock_regions),0,'included location deletion removes dependent regions');
select is((select count(*)::int from public.regional_stock_assessments),0,'included location deletion removes dependent assessments');
select is((select count(*)::int from public.audit_log where organization_id=pg_temp.id(1) and table_name='stock_regions' and operation='DELETE'),2,'location cascade audited');
select * from finish(); rollback;
